-- Strict seed reset and real-user category repair.
-- Real users are preserved. Seed profiles are deleted and reseeded from public/seed only.
-- Seed category is determined only by image folder:
--   /seed/sugarmums/ -> Sugar Mummy, looking for Sugar Guy / Toyboy
--   /seed/sugar-dads/ -> Sugar Daddy, looking for Mistress
--   /seed/mistresses/ -> Mistress, looking for Sugar Daddy
--   /seed/Toboys or Sugarguys/ -> Sugar Guy / Toyboy, looking for Sugar Mummy

alter table public.users add column if not exists preference text;
alter table public.users add column if not exists profile_label text;
alter table public.users add column if not exists member_category text;
alter table public.users add column if not exists looking_for text;
alter table public.users add column if not exists intent_summary text;
alter table public.users add column if not exists photos text[] default '{}'::text[];
alter table public.users add column if not exists is_seed_profile boolean not null default false;
alter table public.users add column if not exists show_in_public boolean not null default true;

delete from public.users
where is_seed_profile = true
   or lower(coalesce(email, '')) like 'seed+%'
   or lower(coalesce(username, '')) like '%_seed_%'
   or lower(coalesce(username, '')) like '%_seed'
   or lower(coalesce(avatar_url, '') || ' ' || coalesce(array_to_string(photos, ' '), '')) like '%/seed/%'
   or lower(coalesce(avatar_url, '') || ' ' || coalesce(array_to_string(photos, ' '), '')) like '%/seed-photos/%'
   or lower(coalesce(avatar_url, '') || ' ' || coalesce(array_to_string(photos, ' '), '')) like '%/pics/%'
   or lower(coalesce(avatar_url, '') || ' ' || coalesce(array_to_string(photos, ' '), '')) like '%genuinesugarmummies.com%';

with fixed as (
    select
        id,
        case
            when lower(coalesce(preference, '')) like 'sugar_mummy%' then 'sugar_mummy'
            when lower(coalesce(preference, '')) like 'sugar_daddy%' then 'sugar_daddy'
            when lower(coalesce(preference, '')) like 'mistress%' then 'mistress'
            when lower(coalesce(preference, '')) like 'toyboy%' or lower(coalesce(preference, '')) like 'sugar_guy%' then 'toyboy'
            when lower(replace(replace(coalesce(profile_label, member_category, ''), '-', '_'), ' ', '_')) in ('sugar_mummy', 'sugarmummy', 'sugar_mum', 'sugarmum') then 'sugar_mummy'
            when lower(replace(replace(coalesce(profile_label, member_category, ''), '-', '_'), ' ', '_')) in ('sugar_daddy', 'sugardaddy') then 'sugar_daddy'
            when lower(replace(replace(coalesce(profile_label, member_category, ''), '-', '_'), ' ', '_')) = 'mistress' then 'mistress'
            when lower(replace(replace(coalesce(profile_label, member_category, ''), '-', '_'), ' ', '_')) in ('toyboy', 'toy_boy', 'toboy', 'sugar_guy', 'sugarguy', 'sugar_boy', 'sugarboy') then 'toyboy'
            else null
        end as label
    from public.users
    where coalesce(is_seed_profile, false) = false
)
update public.users as u
set
    profile_label = fixed.label,
    member_category = fixed.label,
    looking_for = case fixed.label
        when 'sugar_mummy' then 'Sugar Guy / Toyboy'
        when 'sugar_daddy' then 'Mistress'
        when 'mistress' then 'Sugar Daddy'
        when 'toyboy' then 'Sugar Mummy'
        else u.looking_for
    end,
    intent_summary = case fixed.label
        when 'sugar_mummy' then 'I am a Sugar Mummy looking for Sugar Guy / Toyboy.'
        when 'sugar_daddy' then 'I am a Sugar Daddy looking for Mistress.'
        when 'mistress' then 'I am a Mistress looking for Sugar Daddy.'
        when 'toyboy' then 'I am a Sugar Guy / Toyboy looking for Sugar Mummy.'
        else u.intent_summary
    end,
    show_in_public = true
from fixed
where u.id = fixed.id
  and fixed.label in ('sugar_mummy', 'sugar_daddy', 'mistress', 'toyboy');

